import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper
import java.util.UUID
Message processData(Message message) {
    def cases = new JsonSlurper().parseText('''[{"id": "L020_1", "input": "Order SO1001, amount 250", "objective": "MIME encode/decode round trip — business text", "variant": "base", "exact": "Order SO1001, amount 250"}, {"id": "L020_2", "input": "José సాయి 😀", "objective": "MIME encode/decode round trip — UTF-8 Unicode", "variant": "base", "exact": "José సాయి 😀"}, {"id": "L020_3", "input": "line1\\nline2\\r\\nline3", "objective": "MIME encode/decode round trip — line endings", "variant": "base", "exact": "line1\\nline2\\r\\nline3"}, {"id": "L020_4", "input": "", "objective": "MIME encode/decode round trip — empty body", "variant": "base", "exact": ""}, {"id": "L020_5", "input": "", "objective": "MIME encode/decode round trip — repetitive larger payload", "variant": "base", "exact": ""}]''')
    String id = (message.getBody(String) ?: '').trim()
    def c = cases.find { it.id == id }
    if (c == null) throw new IllegalArgumentException('Unknown ScenarioId ' + id + '. Choose: ' + cases.collect {it.id}.join(', '))
    message.setProperty('TRN_Case', c)
    message.setProperty('Variant', c.variant ?: 'base')
    message.setProperty('EntryId', 'TRN_LAB_' + UUID.randomUUID().toString())
    (c.props ?: [:]).each { k,v -> message.setProperty(k,v) }
    (c.inputHeaders ?: [:]).each { k,v -> message.setHeader(k,v) }
    message.setHeader('TRN_ScenarioId',c.id)
    message.setBody(c.inputBinary ? c.inputBinary.decodeBase64() : c.input)
    def log=messageLogFactory.getMessageLog(message)
    if(log!=null) {
        log.addCustomHeaderProperty('TRN_ScenarioId',c.id)
        log.addCustomHeaderProperty('TRN_Expected',c.expectedRuntime ?: (c.negative ? 'FAILED' : 'COMPLETED'))
    }
    return message
}
